<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\ContentItem; use Illuminate\Http\Request; use Illuminate\Support\Str;
class ContentController extends Controller { private function isContributor():bool{return request()->user()?->hasRole('contributor')&&!request()->user()?->hasRole('admin')&&!request()->user()?->hasRole('super-admin');} public function index(Request $request){$q=ContentItem::query();if($request->filled('q'))$q->where('title','like','%'.$request->q.'%');if($request->filled('status'))$q->where('status',$request->status);return view('admin.content.index',['items'=>$q->latest()->paginate(20)->withQueryString()]);} public function create(){return view('admin.content.form',['item'=>new ContentItem]);} public function store(Request $r){$data=$r->validate(['type'=>'required|string|max:80','title'=>'required|string|max:255','slug'=>'nullable|string|max:280|unique:content_items,slug','excerpt'=>'nullable|string','body'=>'nullable|string','status'=>'required|in:draft,pending_review,published,rejected,archived']);$data['slug']=$data['slug']?:Str::slug($data['title']);$data['created_by']=$r->user()->id;$data['updated_by']=$r->user()->id;if($data['status']==='published'){$data['published_by']=$r->user()->id;$data['published_at']=now();}ContentItem::create($data);return redirect('/admin/content')->with('success','Content created.');} public function edit(ContentItem $item){if($this->isContributor() && $item->created_by!==request()->user()->id)abort(403);return view('admin.content.form',compact('item'));} public function update(Request $r,ContentItem $item){if($this->isContributor() && $item->created_by!==$r->user()->id)abort(403);$data=$r->validate(['type'=>'required|string|max:80','title'=>'required|string|max:255','slug'=>'required|string|max:280|unique:content_items,slug,'.$item->id,'excerpt'=>'nullable|string','body'=>'nullable|string','status'=>'required|in:draft,pending_review,published,rejected,archived']);$data['updated_by']=$r->user()->id;if($this->isContributor() && $data['status']==='published')abort(403,'Contributors cannot publish content.');if($data['status']==='published' && !$item->published_at){$data['published_by']=$r->user()->id;$data['published_at']=now();}$item->update($data);return redirect('/admin/content')->with('success','Content updated.');} public function destroy(ContentItem $item){if($this->isContributor() && $item->created_by!==request()->user()->id)abort(403);$item->delete();return back()->with('success','Content archived.');}}
